import dkmeansInitPlusPlus = require( './index' );


// TESTS //

// The function returns a Float64Array...
{
	const k = 3;
	const M = 5;
	const N = 2;

	const out = new Float64Array( k * N );
	const x = new Float64Array( M * N );
	const W1 = new Float64Array( 2 * M );
	const W2 = new Int32Array( k );
	const options = {
		'seed': 1234
	};

	dkmeansInitPlusPlus( 'row-major', M, N, k, 3, 'sqeuclidean', x, N, out, N, W1, 1, W2, 1 ); // $ExpectType Float64Array
	dkmeansInitPlusPlus( 'row-major', M, N, k, 3, 'sqeuclidean', x, N, out, N, W1, 1, W2, 1, options ); // $ExpectType Float64Array
}

// The compiler throws an error if the function is provided a first argument which is not a layout...
{
	const k = 3;
	const M = 5;
	const N = 2;

	const out = new Float64Array( k * N );
	const x = new Float64Array( M * N );
	const W1 = new Float64Array( 2 * M );
	const W2 = new Int32Array( k );

	dkmeansInitPlusPlus( 5, M, N, k, 3, 'sqeuclidean', x, N, out, N, W1, 1, W2, 1 ); // $ExpectError
	dkmeansInitPlusPlus( true, M, N, k, 3, 'sqeuclidean', x, N, out, N, W1, 1, W2, 1 ); // $ExpectError
	dkmeansInitPlusPlus( null, M, N, k, 3, 'sqeuclidean', x, N, out, N, W1, 1, W2, 1 ); // $ExpectError
	dkmeansInitPlusPlus( void 0, M, N, k, 3, 'sqeuclidean', x, N, out, N, W1, 1, W2, 1 ); // $ExpectError
	dkmeansInitPlusPlus( [], M, N, k, 3, 'sqeuclidean', x, N, out, N, W1, 1, W2, 1 ); // $ExpectError
	dkmeansInitPlusPlus( {}, M, N, k, 3, 'sqeuclidean', x, N, out, N, W1, 1, W2, 1 ); // $ExpectError
	dkmeansInitPlusPlus( ( x: number ): number => x, M, N, k, 3, 'sqeuclidean', x, N, out, N, W1, 1, W2, 1 ); // $ExpectError

	dkmeansInitPlusPlus( 5, M, N, k, 3, 'sqeuclidean', x, N, out, N, W1, 1, W2, 1, {} ); // $ExpectError
	dkmeansInitPlusPlus( true, M, N, k, 3, 'sqeuclidean', x, N, out, N, W1, 1, W2, 1, {} ); // $ExpectError
	dkmeansInitPlusPlus( null, M, N, k, 3, 'sqeuclidean', x, N, out, N, W1, 1, W2, 1, {} ); // $ExpectError
	dkmeansInitPlusPlus( void 0, M, N, k, 3, 'sqeuclidean', x, N, out, N, W1, 1, W2, 1, {} ); // $ExpectError
	dkmeansInitPlusPlus( [], M, N, k, 3, 'sqeuclidean', x, N, out, N, W1, 1, W2, 1, {} ); // $ExpectError
	dkmeansInitPlusPlus( {}, M, N, k, 3, 'sqeuclidean', x, N, out, N, W1, 1, W2, 1, {} ); // $ExpectError
	dkmeansInitPlusPlus( ( x: number ): number => x, M, N, k, 3, 'sqeuclidean', x, N, out, N, W1, 1, W2, 1, {} ); // $ExpectError
}

